using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    while (cin >> n && n != 0) {
        string initial, final;
        cin >> initial >> final;

        // Find positions where panels need to be swapped
        vector<int> mismatch;
        for (int i = 0; i < n; i++) {
            if (initial[i] != final[i]) {
                mismatch.push_back(i);
            }
        }

        if (mismatch.empty()) {
            cout << "0\n";
            continue;
        }

        // The optimal strategy: pair mismatches and swap them
        // Minimum cost is achieved by pairing adjacent mismatches
        // because moving the machine between positions costs distance

        int m = mismatch.size();

        // dp[i] = minimum cost to fix first i mismatches
        vector<int> dp(m + 1, INT_MAX);
        dp[0] = 0;

        for (int i = 2; i <= m; i += 2) {
            // Pair mismatch[i-2] with mismatch[i-1]
            dp[i] = dp[i-2] + (mismatch[i-1] - mismatch[i-2]);
        }

        // If there are odd number of mismatches, it's impossible
        if (m % 2 == 1) {
            // This case shouldn't happen with valid input
            // but handle it gracefully
            cout << "0\n";
        } else {
            cout << dp[m] << "\n";
        }
    }

    return 0;
}

