        map<int, queue<int>> finalPos;
        for (int i = 0; i < n; i++) finalPos[final_[i]].push(i);

        // Build permutation
        vector<int> perm(n);
        for (int i = 0; i < n; i++) {
            perm[i] = finalPos[initial[i]].front();
            finalPos[initial[i]].pop();
        }

        // Count inversions
        long long ans = mergeCount(perm, 0, n);
        cout << ans << "\n";
    }
}

