int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    while (cin >> n && n) {
        string s, t;
        cin >> s >> t;

        vector<int> posS, posT;
        for (int i = 0; i < n; ++i) {
            if (s[i] != t[i]) {
                if (s[i] == 'B') posS.push_back(i);
                else posT.push_back(i);
            }
        }

        // For a valid transformation, counts must match.
        // Pair k-th extra black in s with k-th needed black in t.
        int m = (int)posS.size();
        if (m == 0) {
            cout << 0 << '\n';
            continue;
        }

        // Each swap fixes one position from posS and one from posT.
        // If we perform swaps in some order, machine visits endpoints of these pairs.
        // Since we may start anywhere for free and only movement between adjacent panels costs,
        // the minimum total movement equals:
        // sum of pair distances + minimal extra travel to connect all used positions,
        // which is (max endpoint - min endpoint) for an optimal ordering.
        //
        // For these monotone pairs, optimal pairing is by order.
        long long sumPair = 0;
        int mn = n, mx = -1;
        for (int i = 0; i < m; ++i) {
            sumPair += llabs(posS[i] - posT[i]);
            mn = min(mn, min(posS[i], posT[i]));
            mx = max(mx, max(posS[i], posT[i]));
        }

        cout << sumPair + (mx - mn) << '\n';
    }

    return 0;
}

