import java.io.*;
import java.util.*;

public class Main {
    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }

        String next() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            StringBuilder sb = new StringBuilder();
            while (c > ' ') {
                sb.append((char) c);
                c = read();
            }
            return sb.toString();
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        StringBuilder out = new StringBuilder();

        while (true) {
            int n;
            try {
                n = fs.nextInt();
            } catch (Exception e) {
                break;
            }
            if (n == 0) break;

            String a = fs.next();
            String b = fs.next();

            ArrayList<Integer> pos01 = new ArrayList<>(); // a=0, b=1
            ArrayList<Integer> pos10 = new ArrayList<>(); // a=1, b=0

            for (int i = 0; i < n; i++) {
                char ca = a.charAt(i);
                char cb = b.charAt(i);
                if (ca == '0' && cb == '1') pos01.add(i);
                else if (ca == '1' && cb == '0') pos10.add(i);
            }

            int m = pos01.size();
            if (m == 0) {
                out.append(0).append('\n');
                continue;
            }

            long[] p = new long[m + 1];
            long[] q = new long[m + 1];
            for (int i = 1; i <= m; i++) {
                p[i] = pos01.get(i - 1);
                q[i] = pos10.get(i - 1);
            }

            // dpL[i]: minimum cost after processing first i pairs,
            // machine ends at p[i]
            // dpR[i]: same, machine ends at q[i]
            long[] dpL = new long[m + 1];
            long[] dpR = new long[m + 1];

            dpL[1] = Math.abs(p[1] - q[1]); // start at q[1], mark q[1], move to p[1], mark p[1]
            dpR[1] = Math.abs(p[1] - q[1]); // symmetric

            for (int i = 2; i <= m; i++) {
                long dist = Math.abs(p[i] - q[i]);

                dpL[i] = Math.min(
                        dpL[i - 1] + Math.abs(q[i - 1] - q[i]) + dist,
                        dpR[i - 1] + Math.abs(p[i - 1] - q[i]) + dist
                );

                dpR[i] = Math.min(
                        dpL[i - 1] + Math.abs(q[i - 1] - p[i]) + dist,
                        dpR[i - 1] + Math.abs(p[i - 1] - p[i]) + dist
                );
            }

            long ans = Math.min(dpL[m], dpR[m]);
            out.append(ans).append('\n');
        }

        System.out.print(out.toString());
    }
}

