        // For L=4, start at 2 (interior): go to 0 (2), swap(0,2):2, at2; swap(2,4):2, at4; swap(4,6):2, at6; swap(6,0):6; total=2+2+2+2+6=14 > 12. So extreme is best.

        // Thus cost per cycle:
        // L=1: 0
        // L=2: |p1 - p2|
        // L>=3: 2 * (max - min)

        // Now compute total cost.

        // First, we need the positions involved in each cycle.
        int visited[MAXN] = {0};
        int total_cost = 0;
        for (int i = 0; i < n; i++) {
            if (!visited[i]) {
                // collect cycle
                int cycle[MAXN];
                int len = 0;
                int cur = i;
                while (!visited[cur]) {
                    visited[cur] = 1;
                    cycle[len++] = cur;
                    cur = target[cur];
                }
                if (len == 1) continue;
                // find min and max position in this cycle
                int min_pos = n, max_pos = -1;
                for (int j = 0; j < len; j++) {
                    if (cycle[j] < min_pos) min_pos = cycle[j];
                    if (cycle[j] > max_pos) max_pos = cycle[j];
                }
                if (len == 2) {
                    total_cost += max_pos - min_pos;
                } else {
                    total_cost += 2 * (max_pos - min_pos);
                }
            }
        }

        printf("%d\n", total_cost);
    }
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef long long ll;

static int cmp_ll(const void *a, const void *b) {
    ll x = *(const ll *)a;
    ll y = *(const ll *)b;
    if (x < y) return -1;
    if (x > y) return 1;
    return 0;
}

int main(void) {
    int n;
    while (scanf("%d", &n) == 1 && n) {
        char *a = (char *)malloc((n + 5) * sizeof(char));
        char *b = (char *)malloc((n + 5) * sizeof(char));
        scanf("%s %s", a, b);

        ll *posA = (ll *)malloc((n + 5) * sizeof(ll));
        ll *posB = (ll *)malloc((n + 5) * sizeof(ll));
        int ca = 0, cb = 0;

        for (int i = 0; i < n; i++) {
            if (a[i] == 'B') posA[ca++] = i + 1;
            if (b[i] == 'B') posB[cb++] = i + 1;
        }

        if (ca != cb) {
            /* Should not happen for valid inputs, but keep safe. */
            printf("-1\n");
            free(a); free(b); free(posA); free(posB);
            continue;
        }

        int k = 0;
        ll *d = (ll *)malloc((ca + 5) * sizeof(ll));
        for (int i = 0; i < ca; i++) {
            if (posA[i] != posB[i]) {
                d[k++] = posA[i];
                d[k++] = posB[i];
            }
        }

        if (k == 0) {
            printf("0\n");
        } else {
            qsort(d, k, sizeof(ll), cmp_ll);
            ll median = d[k / 2];
            ll ans = 0;
            for (int i = 0; i < k; i++) {
                ll diff = d[i] - median;
                if (diff < 0) diff = -diff;
                ans += diff;
            }
            printf("%lld\n", ans);
        }

        free(a);
        free(b);
        free(posA);
        free(posB);
        free(d);
    }
    return 0;
}
